"""Original fungal chapter: eight Candida questions."""
from qbank_authoring import question,ref,finalize
CG=ref('ECMM/ISHAM/ASM Global Candidiasis Guideline, 2025','https://pubmed.ncbi.nlm.nih.gov/39956121/')
CI=ref('IDSA Candidiasis Guideline—Site-Specific Diagnostic Principles','https://www.idsociety.org/practice-guideline/candidiasis/')
AU=ref('CDC: Clinical Treatment of C. auris Infection','https://www.cdc.gov/candida-auris/hcp/clinical-care/index.html')
AC=ref('CDC: C. auris Infection Control Guidance','https://www.cdc.gov/candida-auris/hcp/infection-control/index.html')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An adult’s blood culture grows Candida. What is the best initial interpretation?', 'Treat it as clinically significant candidemia requiring prompt assessment and therapy',[
 ('Dismiss it routinely as a skin contaminant','Candida in blood is not ordinarily managed as a harmless contaminant.'),('Wait for three more positive cultures before any action','This can delay necessary care.'),('Assume it is equivalent to Candida in sputum','Blood and airway detections have different meanings.')],
 'The sample site determines the clinical significance of fungal detection', '**Candidemia is an invasive infection.**',['Assess hemodynamic status, likely source and organ involvement.','Obtain species identification and susceptibility.'], '**Start suitable therapy and document clearance.**',['Review vascular catheters and other possible sources.','Look for persistent or deep-seated disease when the course warrants it.'],[['Blood','Invasive infection concern'],['Respiratory sample','Often colonization'],['Management','Prompt therapy and source evaluation']],[CG,CI])
q('A critically ill nonneutropenic adult has candidemia and prior azole exposure. Which initial class is generally preferred?', 'An echinocandin',[
 ('Low-dose fluconazole irrespective of susceptibility and severity','Critical illness and prior exposure make automatic use inappropriate.'),('Voriconazole as the only agent active against every Candida','Activity and resistance vary.'),('An antibacterial carbapenem alone','It does not treat Candida.')],
 'Initial invasive-Candida therapy should account for severity and resistance risk', '**Echinocandins are preferred initial options for many candidemia patients.**',['Species and prior exposure affect selection.','A susceptible stable selected patient may later transition to an oral azole.'], '**Review the source and microbiological response.**',['Monitor toxicity and drug interactions.','Deep sites such as eye or CNS disease require site-specific penetration assessment.'],[['Initial critical illness','Often echinocandin'],['Species/DST','Guides refinement'],['Deep site','May change drug choice']],[CG],style='clinical_scenario')
q('For candidemia without metastatic complications, how is the usual minimum treatment period anchored?', 'At least 14 days after documented bloodstream clearance and resolution of attributable symptoms',[
 ('Fourteen days from the first fever regardless of ongoing positive cultures','Clearance and response matter.'),('Stop after the first antifungal dose if the patient looks better','That is inadequate.'),('A fixed six-month course for every uncomplicated episode','That is not the standard minimum for the stated situation.')],
 'Persistent bloodstream positivity resets the interpretation of adequate treatment', '**Serial cultures document clearance.**',['Deep foci or persistent infection require a different duration.','Immune status and clinical response influence the complete plan.'], '**Investigate nonclearance rather than only extending the calendar.**',['Assess catheter, abdominal or other sources.','Review susceptibility and drug exposure.'],[['Starting anchor','Documented clearance'],['Additional requirement','Symptom resolution'],['Complicated disease','Site-specific longer course']],[CG,CI])
q('Which factor is essential when deciding whether to remove a central line in candidemia?', 'Whether it is a likely source and whether safe effective source control is feasible in the individual patient',[
 ('Keep every line because antifungals reliably sterilize every biofilm','Retention can sustain infection.'),('Remove all implanted devices blindly without assessing the source or procedural risk','Source control must be anatomically and clinically informed.'),('Catheter assessment is unnecessary if Candida species is known','Species identification does not determine source control alone.')],
 'A vascular device can provide a persistent fungal reservoir', '**Timely removal is important when the catheter is the suspected source and removal is safe.**',['Other sources, including the abdomen, must be assessed.','Neutropenia and access issues can complicate the decision.'], '**Coordinate antifungals and source control.**',['Follow cultures until clearance.','Persistent positivity should trigger renewed source investigation.'],[['Possible source','Catheter biofilm'],['Decision','Source likelihood and safe removal'],['Follow-up','Document bloodstream clearance']],[CG,CI])
q('An asymptomatic catheterized adult has Candida in urine, without neutropenia or a planned urological procedure. What is generally appropriate?', 'Address removable predisposing factors rather than automatically prescribe antifungals',[
 ('Treat every urine isolate as candidemia','Candiduria often represents colonization.'),('Use an echinocandin automatically because urine concentration is irrelevant','Urinary-site drug exposure matters.'),('Ignore new fever, obstruction or symptoms if they later develop','A changed clinical syndrome needs reassessment.')],
 'Candida detection in urine is often not invasive urinary infection', '**Remove an unnecessary catheter when possible.**',['Diabetes, antibiotics and devices can contribute to colonization.','High-risk groups and urological manipulation are important exceptions.'], '**Investigate a true symptomatic or obstructed syndrome separately.**',['Species and susceptibility affect treatment if needed.','Do not infer infection from colony count alone in a catheterized patient.'],[['Asymptomatic candiduria','Often colonization'],['Initial step','Remove predisposing factors'],['Exceptions','Selected high-risk/procedural settings']],[CI],style='clinical_scenario')
q('A ventilated patient has Candida in an endotracheal aspirate but no evidence of invasive fungal disease. What is the usual interpretation?', 'Airway colonization rather than Candida pneumonia requiring treatment solely from this result',[
 ('The culture definitively proves invasive Candida pneumonia','True Candida pneumonia is uncommon and needs stronger evidence.'),('Every respiratory Candida result mandates systemic amphotericin','This promotes unnecessary toxicity.'),('The result excludes bacterial VAP','A colonizer does not exclude another pathogen.')],
 'A nonsterile-site culture can misdirect therapy', '**Respiratory Candida isolation commonly reflects colonization.**',['Evaluate the actual pneumonia syndrome and other organisms.','Invasive tissue evidence has a different significance.'], '**Avoid treating the culture alone.**',['Investigate systemic signs according to the full differential.','Assess candidemia separately if blood cultures or other findings support it.'],[['Airway isolate','Usually colonization'],['Blood/tissue evidence','Different invasive significance'],['Treatment','Requires a coherent disease diagnosis']],[CI],style='clinical_scenario')
q('Why does identification of Candida auris require attention beyond individual antifungal selection?', 'It can be drug resistant, persist in health-care environments and spread between patients',[
 ('It is always susceptible to fluconazole','Resistance is common and susceptibility testing matters.'),('Colonization automatically requires systemic treatment','CDC does not recommend treating colonization without infection.'),('Routine antibacterial therapy eradicates environmental and patient reservoirs','It does not provide an adequate fungal-control strategy.')],
 'A resistant yeast can create a health-care transmission problem', '**Use species confirmation, susceptibility and appropriate infection-control measures.**',['Echinocandins are common initial infection-treatment options in adults.','Resistance or clinical failure can require expert alternatives.'], '**Coordinate clinical and infection-prevention teams.**',['Use suitable environmental disinfection and precautions.','Distinguish infection treatment from colonization management.'],[['Patient','Treat actual infection'],['Laboratory','Confirm species and susceptibility'],['System','Prevent transmission and environmental persistence']],[AU,AC])
q('A critically ill patient has a positive beta-D-glucan. Which interpretation is correct?', 'It supports selected invasive-fungal possibilities but is not specific for Candida or sufficient alone to establish a treatable invasive infection',[
 ('It identifies the Candida species and susceptibility','It does not.'),('It is positive in every fungal infection including all mucormycosis','Sensitivity varies and some fungal groups are poorly detected.'),('A single positive result makes source assessment unnecessary','Clinical and microbiological integration remains essential.')],
 'A fungal cell-wall marker is a probability tool', '**False positives and alternative fungal causes occur.**',['The value depends on host risk and specimen/testing context.','A negative result also has organism- and population-specific limits.'], '**Use the result to support a diagnostic strategy.**',['Obtain cultures, imaging or direct-site specimens as indicated.','Avoid indiscriminate therapy in a low-probability patient solely from one marker.'],[['Marker','Beta-D-glucan'],['Limit','Not species-specific'],['Diagnosis','Host, site and organism evidence together']],[CG,CI])

if __name__=='__main__':print('Fungal Candida block: '+str(len(rows))+' questions drafted')
